 // tunic and armor
 ctx.fillStyle=flash?'#fff':'#38394e';ctx.fillRect(-10,-8,20,24);ctx.fillStyle='#bd9c5e';ctx.fillRect(-2,-7,4,22);ctx.fillStyle='#cfb377';ctx.fillRect(-10,2,20,3);
