 ctx.fillStyle=flash?'#fff':'#dbc6a0';ctx.beginPath();ctx.arc(0,-17,9,0,Math.PI*2);ctx.fill();ctx.fillStyle='#242131';ctx.beginPath();ctx.moveTo(-10,-18);ctx.lineTo(-5,-29);ctx.lineTo(9,-26);ctx.lineTo(11,-17);ctx.lineTo(2,-20);ctx.closePath();ctx.fill();ctx.fillStyle='#bde4e4';ctx.fillRect(4,-18,3,2);
