function drawBoss(t){if(!boss.alive)return;const x=boss.x-camera,y=boss.y;ctx.save();ctx.translate(x+boss.w/2,y+boss.h/2);ctx.globalAlpha=boss.hit>0?.55:1;ctx.shadowBlur=26;ctx.shadowColor='#9a4666';ctx.fillStyle='#342d42';ctx.beginPath();ctx.moveTo(-26,-37);ctx.lineTo(-34,-50);ctx.lineTo(-13,-44);ctx.lineTo(0,-59);ctx.lineTo(12,-44);ctx.lineTo(35,-52);ctx.lineTo(26,-29);ctx.lineTo(27,39);ctx.lineTo(13,50);ctx.lineTo(-15,50);ctx.lineTo(-28,35);ctx.closePath();ctx.fill();ctx.fillStyle='#704451';ctx.fillRect(-18,-31,36,49);ctx.fillStyle='#c48c6a';ctx.fillRect(-17,-43,34,13);ctx.fillStyle='#e6c982';ctx.fillRect(-11,-38,5,3);ctx.fillRect(6,-38,5,3);ctx.fillStyle='#1b1a2a';ctx.fillRect(-23,11,15,34);ctx.fillRect(8,11,15,34);ctx.strokeStyle='#c8ad72';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(24,-28);ctx.lineTo(41,32);ctx.stroke();ctx.restore();if(boss.active){ctx.fillStyle='#1a1826';ctx.fillRect(W/2-125,62,250,9);ctx.fillStyle='#9e5666';ctx.fillRect(W/2-125,62,250*boss.hp/boss.maxHp,9);ctx.strokeStyle='#d2b778';ctx.strokeRect(W/2-125,62,250,9);ctx.fillStyle='#e2d4b5';ctx.font='10px Cinzel';ctx.textAlign='center';ctx.fillText('THE HOLLOW KING',W/2,55)}}
