input.newString:
function render(t,dt){ctx.save();if(shake>0){ctx.translate((Math.random()-.5)*shake,(Math.random()-.5)*shake);shake*=.85}drawBackground(t);drawWorld(t);enemies.forEach(e=>drawEnemy(e,t));drawBoss(t);drawProjectiles();drawHero(t);drawMotes(dt);if(state==='playing'){drawHUD();drawPrompt()}ctx.restore()}
function hurt(amount=1){if(player.inv>0||state!=='playing')return;player.hp-=amount;player.inv=1.15;shake=9;addMote(player.x+13,player.y+20,'#df6e79',13);playTone(110,.22,'sawtooth',.045);if(player.hp<=0){player.hp=0;state='dead';document.getElementById('endEyebrow').textContent='The keep claims another';document.getElementById('endTitle').innerHTML='A LIGHT<br><span>GOES OUT</span>';document.getElementById('endText').textContent='Even the bravest flame can gutter in these halls. The sigils remain yours to reclaim — rise, and try again.';document.getElementById('endScreen').classList.remove('hidden')}}
function damageEnemy(e){if(!e.alive||slashHits.has(e))return;slashHits.add(e);e.hp--;addMote(e.x+13,e.y+12,e.type==='wraith'?'#ad9bf0':'#d6b977',10);playTone(260,.07,'triangle',.035);if(e.hp<=0){e.alive=false;addMote(e.x+13,e.y+18,'#e6c982',17)}}
function update(dt,t){if(state!=='playing')return;dt=Math.min(dt,.035);player.anim+=dt;player.inv=Math.max(0,player.inv-dt);player.attack=Math.max(0,player.attack-dt);player.attackCd=Math.max(0,player.attackCd-dt);
 const axis=(keys.right?1:0)-(keys.left?1:0);if(axis){player.vx+=axis*1800*dt;player.face=axis}else player.vx*=Math.pow(.001,dt);player.vx=clamp(player.vx,-210,210);
 if(keys.jump){if(player.onGround){player.vy=-520;player.onGround=false;player.airJump=false;playTone(340,.08,'sine',.022)}else if(player.airJump&&player.vy>30){player.vy=-480;player.airJump=false;addMote(player.x+13,player.y+42,'#b4dce0',6);playTone(480,.09,'sine',.025)}keys.jump=false}
 player.vy=Math.min(800,player.vy+1450*dt);const oldBottom=player.y+player.h;player.x=clamp(player.x+player.vx*dt,0,worldW-player.w);player.y+=player.vy*dt;player.onGround=false;
 for(const p of platforms){if(player.vy>=0&&oldBottom<=p.y+5&&player.y+player.h>=p.y&&player.x+player.w>p.x&&player.x<p.x+p.w){player.y=p.y-player.h;player.vy=0;player.onGround=true;player.airJump=true}}
 // locked gate stops the player until the three sigils are gathered
 if(collected()<3&&player.x>4070&&player.x<4140){player.x=4070;player.vx=0}
 // collect the three keep sigils
 for(const s of sigils)if(!s.got&&Math.hypot(player.x+13-s.x,player.y+20-s.y)<38){s.got=true;addMote(s.x,s.y,'#f4df9b',24);playTone(660,.25,'sine',.055);toast(s.name+' recovered · '+collected()+' / 3',2100)}
 // shrine interaction is an intentional checkpoint and full heal
 if(keys.interact){keys.interact=false;let shrine=shrines.find(s=>!s.used&&Math.abs(player.x-s.x)<62&&player.y+player.h>groundY-95);if(shrine){shrine.used=true;player.checkpoint=shrine.x;player.hp=player.maxHp;player.flask=2;addMote(shrine.x,groundY-88,'#9bdbd8',20);playTone(510,.3,'sine',.05);toast('A quiet place. Your strength returns.',2200)}}
 if(keys.attack&&player.attackCd<=0){player.attack=.25;player.attackCd=.36;slashHits.clear();playTone(210,.07,'triangle',.035);keys.attack=false}else if(!keys.attack)keys.attack=false;
 if(player.attack>.07){for(const e of enemies)if(e.alive){let dx=(e.x+13)-(player.x+13),dy=(e.y+15)-(player.y+22);if(Math.abs(dx)<55&&Math.abs(dy)<48&&Math.sign(dx)===player.face)damageEnemy(e)}if(boss.alive&&boss.active){let dx=(boss.x+27)-(player.x+13),dy=(boss.y+45)-(player.y+22);if(Math.abs(dx)<72&&Math.abs(dy)<72&&Math.sign(dx)===player.face&&!slashHits.has(boss)){slashHits.add(boss);boss.hp--;boss.hit=.13;shake=5;addMote(boss.x+27,boss.y+40,'#edc879',10);playTone(170,.1,'sawtooth',.04);if(boss.hp<=0){boss.alive=false;state='won';document.getElementById('endEyebrow').textContent='The bells are quiet';document.getElementById('endTitle').innerHTML='THE CROWN<br><span>IS BROKEN</span>';document.getElementById('endText').textContent='The Hollow King is no more. Dawn slips over Gloamkeep, and for the first time in a hundred years, the bells ring for the living.';document.getElementById('endScreen').classList.remove('hidden');playTone(740,.8,'sine',.06)}}}}
 // living threats patrol their broken halls
 for(const e of enemies)if(e.alive){e.x+=e.dir*e.speed*dt;if(e.x<e.range[0]||e.x>e.range[1])e.dir*=-1;if(Math.abs(player.x-e.x)<28&&Math.abs(player.y-e.y)<40)hurt()}
 if(collected()===3&&player.x>4165&&!boss.active&&boss.alive){boss.active=true;toast('The Hollow King stirs.',2200);playTone(90,.7,'sawtooth',.05)}
 if(boss.active&&boss.alive){boss.hit=Math.max(0,boss.hit-dt);let dx=player.x-boss.x;if(Math.abs(dx)>95){boss.x+=Math.sign(dx)*55*dt;boss.dir=Math.sign(dx)}boss.attack-=dt;if(boss.attack<=0){boss.attack=1.75;projectiles.push({x:boss.x+26,y:boss.y+37,vx:Math.sign(dx)*210,vy:-20,r:8});playTone(140,.16,'sawtooth',.025)}}
 for(let i=projectiles.length-1;i>=0;i--){const p=projectiles[i];p.x+=p.vx*dt;p.y+=p.vy*dt;if(Math.abs(p.x-(player.x+13))<p.r+12&&Math.abs(p.y-(player.y+23))<p.r+17){hurt();projectiles.splice(i,1)}else if(p.x<camera-30||p.x>camera+W+30)projectiles.splice(i,1)}
 if(player.y>H+55){hurt();player.x=player.checkpoint;player.y=groundY-player.h;player.vy=0;player.vx=0}
 if(toastTimer>0){toastTimer-=dt*1000;if(toastTimer<=0)document.getElementById('toast').classList.remove('show')}
 const target=clamp(player.x-W*.42,0,worldW-W);camera+=(target-camera)*Math.min(1,dt*5.5);
}

